// Organizational Leadership Practice Test 3. Original questions written for Valus from the HOSA 2026–27
// test plan, slightly harder than the sample items. HOSA facts follow the Valus Organizational
// Leadership lessons, which summarize the HOSA Handbook (Sections A–C), the HOSA website and
// The First Fifty Years 1976–2026; parliamentary items follow RONR In Brief.
import {q, mix} from './q.js';
const HB='HOSA Handbook, Sections A–C', WEB='HOSA website (Voting Delegate resources)', FFY='HOSA, The First Fifty Years 1976–2026', BRIEF='Robert’s Rules of Order Newly Revised In Brief';
const VD='Voting Delegate Role and Responsibilities', PP='Parliamentary Procedure', INC='HOSA Inc.', ORG='Organizational Structure of HOSA', HIST='History of HOSA', EC='Positions and Responsibilities of the Executive Council', MEM='Membership';

export default {
 id:'organizational-leadership-3',
 event:'Organizational Leadership',
 title:'Practice Test 3',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'the HOSA Handbook (Sections A–C), the HOSA website, The First Fifty Years 1976–2026 and Robert’s Rules of Order Newly Revised In Brief',
 plan:[{area:VD,weight:24},{area:PP,weight:24},{area:INC,weight:16},{area:ORG,weight:12},{area:HIST,weight:12},{area:EC,weight:8},{area:MEM,weight:4}],
 questions:mix([
  q(VD,'Using HOSA’s allocation table, how many voting delegates does a chartered association with 80 members receive?','1',['0','2','3'],'A','The table gives 1 delegate for 25–100 members and 2 delegates only once membership reaches 101–1,000, so 80 members earn one delegate.',WEB),
  q(VD,'A chartered association has 9,500 members. How many voting delegates does it receive?','7',['5','6','8'],'B','3,001–5,000 members earn 4 delegates, and one more is added for each additional 2,000 members: 5,001–7,000 = 5, 7,001–9,000 = 6 and 9,001–11,000 = 7.',WEB),
  q(VD,'Chartered association X has 3,500 members and Y has 2,900. How do their delegate counts compare?','X has 4 and Y has 3',['Both have 3 delegates','X has 5 and Y has 4','Both have 4 delegates'],'C','1,001–3,000 members earn 3 delegates and 3,001–5,000 earn 4, so the 600-member difference crosses a boundary and gives X one more delegate.',WEB),
  q(VD,'A chartered association’s bylaws and policies do not outline how voting delegates are chosen. What may it do?','Use the HOSA Voting Delegate Test to select them',['Ask HOSA Headquarters to name its delegates','Send no delegates to that year’s ILC','Let the Executive Council choose for it'],'D','Selection is at the State Advisor’s discretion or follows the bylaws and policies; if no process is clearly outlined, the chartered association may use the HOSA Voting Delegate Test.',WEB),
  q(VD,'A member hopes to become a voting delegate next year. What is the best first step?','Ask the State Advisor about the selection process',['Email the Executive Council for a nomination','Wait for ILC staff to contact the chapter','Register for the Business Session online'],'A','Processes differ among chartered associations, so members interested in serving should check with their State Advisor about deadlines, test dates and steps.',WEB),
  q(VD,'At ILC, the Business Session overlaps with an event final a delegate wants to watch. What should the delegate do?','Attend the Business Session, a required duty',['Watch the final and catch up from notes later','Send a chapter member to vote in their place','Leave a signed ballot with the chair beforehand'],'B','Delegates must attend and take part in the Business Session, where official votes happen; representing the chartered association comes before personal plans.',WEB),
  q(VD,'Before reviewing all candidate materials, a delegate promises their vote to a candidate. Why is this a problem?','It closes the delegate’s mind before all evidence is in',['Promises are binding under Robert’s Rules','Candidates may not speak with delegates at all','Only the State Advisor may promise votes'],'C','Delegates should avoid promises to candidates or other delegates; keeping an open mind until the vote lets them evaluate every candidate fairly on the evidence.',WEB),
  q(VD,'Some items in the Voting Delegate Packet are confidential until released. What should a delegate do?','Follow the instructions on what may be shared and when',['Post a summary so members can comment early','Share it only with friends in other states','Ignore the notice because delegates represent members'],'D','Delegates are trusted with information that may be confidential until released, so integrity means following instructions about what can be shared and when.',WEB),
  q(VD,'Why does a delegation agree on a candidate rubric before reviewing applicants?','So everyone rates candidates by the same standards',['So the State Advisor can cast every vote','So candidates can be ranked by popularity','So the caucus can skip discussing candidates'],'A','Agreeing on criteria first, such as leadership, HOSA knowledge, communication and vision, makes ratings consistent, reduces bias and lets delegates explain decisions.',WEB),
  q(VD,'After the Meet the Candidates Breakfast, a candidate’s answers change a delegate’s view. What is the best response?','Update the rating based on the new evidence',['Keep the first rating to stay consistent','Ignore the breakfast since it is optional','Ask the candidate to withdraw from the race'],'B','Revisiting ratings after the breakfast is part of fair judgment; new evidence from a candidate’s responses may properly change an evaluation.',WEB),
  q(VD,'Which is the second stated purpose of the Organizational Leadership event, besides helping select delegates?','Building members’ knowledge of HOSA and parliamentary procedure',['Ranking chapters by their total membership','Electing the officers of each local chapter','Training chapter advisors to run their State Leadership Conferences'],'C','The event has a two-fold purpose: helping chartered associations select voting delegates and encouraging members to develop and apply knowledge of HOSA and parliamentary procedure.',WEB),
  q(VD,'A delegate is unsure how to make a certain motion during the Business Session. What is an appropriate step?','Ask a parliamentary inquiry through the chair',['Leave the room until the vote is called','Make the motion and let the chair fix it','Ask another state’s delegate to make it'],'D','A parliamentary inquiry asks the chair a procedural question; delegates may also follow the guidance from orientation and their own delegation.',WEB),
  q(PP,'Unless the bylaws say otherwise, what is a quorum under Robert’s Rules?','A majority of the members',['Two-thirds of the members present','Any number of members who attend','One-fourth of the full membership'],'A','A quorum is the minimum number needed to conduct business; RONR sets it at a majority of the members unless the bylaws provide otherwise.',BRIEF),
  q(PP,'An urgent matter arises, so the assembly wants to set the pending motion aside temporarily. Which motion fits?','Lay on the table',['Postpone indefinitely','Rescind the motion','Division of the question'],'B','Lay on the table sets a pending motion aside temporarily so urgent business can be handled; take from the table later resumes it.',BRIEF),
  q(PP,'A motion needs more study before the assembly decides. Which subsidiary motion sends it to a small group?','Commit or refer',['Lay on the table','Postpone indefinitely','Call for the orders of the day'],'C','Commit (refer) sends a pending motion to a committee for study or to work out details, which then reports back to the assembly.',BRIEF),
  q(PP,'What vote is needed to adopt a motion to limit or extend the limits of debate?','Two-thirds',['A majority','A plurality','No vote; the chair decides'],'D','Motions that limit members’ rights, such as limiting or extending debate, closing debate and suspending the rules, require a two-thirds vote.',BRIEF),
  q(PP,'The assembly wants to set aside one of its adopted rules for one item. Which motion and vote apply?','Suspend the rules, by a two-thirds vote',['Suspend the rules, by a majority vote','Point of order, ruled on by the chair','Appeal, decided by a tie in the assembly'],'A','Suspend the rules lets the assembly do something its rules would otherwise prevent; because it limits members’ rights, it needs a two-thirds vote.',BRIEF),
  q(PP,'During debate, the hall is so noisy that members cannot hear. Which motion addresses this?','Raise a question of privilege',['Move to postpone indefinitely','Move the previous question','Move to commit the motion'],'B','A question of privilege is a privileged motion for urgent matters about the comfort or rights of the assembly, such as noise in the hall.',BRIEF),
  q(PP,'The assembly has drifted away from its agenda. Which motion demands that the agenda be followed?','Call for the orders of the day',['Raise a question of privilege','Lay the pending motion on the table','Request for information'],'C','A call for the orders of the day is a privileged motion demanding that the assembly follow its agenda or order of business.',BRIEF),
  q(PP,'A member doubts the chair’s announced result of a voice vote. Which motion demands a rising or counted vote?','Division of the assembly',['Division of the question','Appeal from the chair','Motion to reconsider'],'D','Division of the assembly demands a rising (or counted) vote to verify an uncertain voice vote; division of the question instead splits a motion into parts.',BRIEF),
  q(PP,'A member wants to ask a factual question about the budget figures in the pending motion. Which request fits?','Request for information',['Parliamentary inquiry','Point of order','Question of privilege'],'A','A request for information asks a factual question about the business; a parliamentary inquiry asks a question about procedure instead.',BRIEF),
  q(PP,'A primary amendment is pending. What does a secondary amendment change?','The wording of the primary amendment',['The wording of the main motion directly','The pending secondary amendment','The order of business for the meeting'],'B','A primary amendment amends the main motion, a secondary amendment amends the primary amendment and third-degree amendments are not allowed.',BRIEF),
  q(PP,'A motion is to buy a projector. Which amendment would the chair rule out of order?','Strike “projector” and insert “a trip to the beach”',['Insert “for under $500” after “projector”','Strike “a projector” and insert “two projectors”','Add “for the chapter office” at the end'],'C','Amendments must be germane, closely related to the subject of the motion; replacing the projector with an unrelated trip changes the subject entirely.',BRIEF),
  q(PP,'A motion needing two-thirds gets 60 yes and 31 no votes. What is the result?','Lost, because 60 is less than twice 31',['Adopted, because 60 is a majority of 91','Adopted, because it passes 60% support','Lost, because abstentions were not counted'],'D','Two-thirds means at least twice as many yes votes as no votes. Twice 31 is 62, so 60 yes votes fall short and the motion is lost.',BRIEF),
  q(INC,'Which action best shows a board member acting in good faith toward the organization?','Voting for what serves the mission after studying the facts',['Voting to help a friend win a vendor contract','Skipping meetings while still voting by proxy','Approving large spending without reading the budget or reports'],'A','Board duties include acting in good faith and in the organization’s best interest and following its governing documents, which requires informed decisions.',HB),
  q(INC,'A board wants to take an action its own bylaws forbid. What is the correct course?','Amend the bylaws properly first, or not take it',['Suspend the bylaws by a majority vote','Take the action and record it as policy','Let staff take the action on behalf of the board'],'B','Bylaws rank above the parliamentary authority and cannot be suspended unless they allow it; the board must follow its governing documents or amend them properly.',HB),
  q(INC,'What is the main purpose of a nonprofit organization’s budget?','To plan how money will be raised and spent for the mission',['To show how profits will be paid to the owners','To list the officers elected each year','To replace the need for financial reports and audits each year'],'C','Budgets are part of fiduciary responsibility: they plan income and spending so resources serve the mission and can be compared with later financial reports.',HB),
  q(INC,'In the hierarchy of rules, which ranks lowest?','Standing rules and policies',['The parliamentary authority','Special rules of order','The bylaws of the organization'],'D','The order runs from applicable laws to the charter, bylaws, special rules of order, the parliamentary authority and finally standing rules and policies.',HB),
  q(INC,'Which item would least likely appear in an organization’s bylaws?','The menu for the next banquet',['The officers and their election','How the bylaws are amended','The qualifications for membership'],'A','Bylaws cover name, purpose, membership, officers, meetings, boards, committees, the parliamentary authority and amendment; event details belong elsewhere.',HB),
  q(INC,'Which document do both HOSA as a student organization and HOSA, Inc. have?','Bylaws',['Only a policy manual','A single shared ballot','Only articles of a club'],'B','The Handbook distinguishes the student organization from HOSA, Inc., notes that both have bylaws and says Policy and Procedures Manuals hold the details.',HB),
  q(INC,'How should a nonprofit’s mission statement guide its board?','It sets the purpose every decision should serve',['It replaces the bylaws once adopted','It lists each officer’s daily tasks','It is used only on brochures and other promotional material'],'C','A nonprofit exists to serve a mission rather than owners, so the board measures decisions, budgets and programs against that purpose.',HB),
  q(INC,'Which practice best shows accountability in nonprofit governance?','Reporting decisions and finances openly to members',['Keeping all spending decisions private','Letting one officer control every account','Skipping the yearly audit whenever money is tight'],'D','Ethical governance includes transparency, accountability and decisions that serve members, supported by financial reports, audits and conflict-of-interest policies.',HB),
  q(ORG,'Which list puts HOSA’s levels in order from local to international?','Chapter, chartered association, international',['Chartered association, chapter, international','Region, chapter, chartered association','International, region, chapter'],'A','Local chapters at schools and colleges form chartered associations (usually states), which together make up the international organization.',HB),
  q(ORG,'What is a chartered association, in most cases?','A state or similar unit of HOSA',['A single school’s local chapter','A sponsor of a competitive event','A committee of the Executive Council'],'B','Chartered associations are typically states or similar units chartered by the international organization, led by State Advisors and state officers.',HB),
  q(ORG,'Which level holds the State Leadership Conference?','The chartered association',['The local chapter','HOSA Headquarters only','The Executive Council'],'C','Chartered associations, led by State Advisors and state officers, hold State Leadership Conferences, where state officers are usually elected.',HB),
  q(ORG,'What do HOSA’s partner organizations commonly provide?','Resources, scholarships and recognition',['Votes in the Business Session','State officers for each chapter','Bylaws for chartered associations'],'D','HOSA partners with health care organizations, event sponsors and other groups that provide resources, scholarships and recognition for members.',HB),
  q(ORG,'How does HOSA group chartered associations for representation?','Into regions',['Into divisions','Into chapters','Into caucuses'],'A','HOSA groups chartered associations into regions, which can be represented in leadership roles; divisions instead describe types of members.',HB),
  q(ORG,'At every level of HOSA, what is the usual division of roles?','Adult advisors guide and student officers lead',['Students advise and adult officers lead','Staff vote and students only observe','Sponsors lead and advisors only fund'],'B','Chapter advisors, State Advisors and Headquarters staff provide guidance, while student officers lead at the chapter, state and international levels.',HB),
  q(HIST,'Before HOSA adopted the name HOSA-Future Health Professionals, what did the letters HOSA stand for?','Health Occupations Students of America',['Health Organization of Student Advocates','Hospital Occupations Service Association','Health and Safety Officers of America'],'C','HOSA began as Health Occupations Students of America, serving students in health occupations education, and later adopted HOSA-Future Health Professionals.',FFY),
  q(HIST,'HOSA was founded in 1976 mainly to provide what for students?','Leadership development and career preparation',['Hospital jobs and paid internships','Medical licenses and certifications for graduates','Sports teams for health programs'],'D','HOSA was founded to provide leadership development and career preparation for students in health occupations and health science education programs.',FFY),
  q(HIST,'Which statement best describes HOSA’s first fifty years?','Steady growth in members, chartered associations and events',['A shrinking organization with fewer events','No changes since its founding in 1976','A shift away from health careers toward general student leadership'],'A','Over five decades HOSA grew in membership, chartered associations and competitive events, milestones recorded in The First Fifty Years 1976–2026.',FFY),
  q(HIST,'Adding a new division of members is an example of which kind of milestone in HOSA’s history?','Expansion of membership divisions',['A change in parliamentary authority','A new founding of the organization','A merger of chartered associations'],'B','Milestones often tested include first conferences, expansion of chartered associations, membership milestones, new divisions and the adoption of the current name.',FFY),
  q(HIST,'Besides the mission, which identity items does the HOSA Handbook describe?','Motto, creed, emblem and colors',['Anthem, flag, mascot and seal','Budget, audit, charter and logo','Oath, uniform, trophy and pin'],'C','HOSA’s identity includes its mission along with its motto, creed, emblem and colors, all described in the HOSA Handbook with exact wording to learn.',HB),
  q(HIST,'What does The First Fifty Years 1976–2026 tell the story of?','HOSA’s founding, early leaders and first conferences',['The rules for running a business meeting under Robert’s Rules','Each state’s current competitive results','The finances of each local chapter'],'D','The First Fifty Years 1976–2026 publication tells the story of HOSA’s founding, its early leaders and first conferences, and its growth over five decades.',FFY),
  q(EC,'Under general parliamentary officer duties, which officer keeps the records of meetings?','The secretary',['The president','The treasurer','The parliamentarian'],'A','Parliamentary procedure gives general officer duties: the president presides, the vice president assists and presides when needed and the secretary keeps records.',BRIEF),
  q(EC,'Which quality is best described as putting members’ needs ahead of personal recognition?','Servant leadership',['Popular leadership','Directive authority','Personal branding'],'B','Effective student officers show servant leadership, communication skills, knowledge of HOSA, reliability, teamwork, professionalism and a clear vision for members.',HB),
  q(EC,'Executive Council officers keep in regular contact with which groups?','Chartered associations',['Only the event judges','Only national sponsors','Only other CTSO officers'],'C','Executive Council officers represent members, promote HOSA, help lead conference activities, communicate with chartered associations and model leadership.',HB),
  q(EC,'Which task is part of an Executive Council officer’s role at conferences?','Helping plan and lead conference activities',['Grading competitive event tests','Choosing each state’s delegates','Setting each chartered association’s dues'],'D','Executive Council officers help plan and lead conference activities as part of representing members and modeling leadership at the international level.',HB),
  q(MEM,'What role do professional members play in HOSA?','They support student members',['They compete in secondary events','They elect the Executive Council','They lead local chapters as officers'],'A','HOSA divisions include middle school, secondary and postsecondary/collegiate active members, plus alumni and professional members who support students.',HB),
  q(MEM,'What must be true for a member to compete or serve in HOSA?','The member must be properly affiliated',['The member must have been a delegate','The member must hold a state office','The member must be over 18 years old'],'B','Competitive event guidelines specify eligible divisions, and members must be properly affiliated through their chapter and chartered association to compete and serve.',HB)
 ],7942)
};
